  "stats.help.choose": {"pt": "O que você escolhe", "en": "What you choose"},
  "stats.help.step": {"pt": "Quantos segundos antes e depois de cada marcação entram nas duas médias comparadas. Curta demais fica ruidosa; longa demais invade o patamar vizinho.", "en": "How many seconds before and after each marker go into the two compared means. Too short is noisy; too long reaches into the neighbouring level."},
  "stats.help.intervalTable": {"pt": "Tabela de intervalos", "en": "Interval table"},
  "stats.col.interval": {"pt": "intervalo", "en": "interval"},
  "stats.help.interval": {"pt": "Vai de uma marcação até a seguinte (a última vai até o fim do sinal). O trecho antes da primeira marcação também entra.", "en": "Goes from one marker to the next (the last one goes to the end of the signal). The stretch before the first marker is included too."},
  "stats.help.startEnd": {"pt": "início, fim", "en": "start, end"},
  "stats.help.startEndText": {"pt": "Limites do intervalo, em segundos do arquivo.", "en": "Limits of the interval, in seconds of the file."},
  "stats.help.n": {"pt": "Amostras válidas no trecho; leituras ausentes não contam.", "en": "Valid samples in the stretch; missing readings do not count."},
  "stats.help.meanStd": {"pt": "média, σ", "en": "mean, σ"},
  "stats.help.meanStdText": {"pt": "Média e desvio-padrão de todas as amostras do intervalo. Com transitório ou deriva, o σ mistura flutuação e tendência — compare com o ruído.", "en": "Mean and standard deviation of all samples in the interval. With a transient or drift, σ mixes fluctuation and trend — compare it with the noise."},
  "stats.help.minMax": {"pt": "mín, máx, pico a pico", "en": "min, max, peak to peak"},
  "stats.help.minMaxText": {"pt": "Extremos e a diferença entre eles; sensíveis a um único pico isolado.", "en": "The extremes and the difference between them; sensitive to a single isolated spike."},
  "stats.col.drift": {"pt": "deriva (/s)", "en": "drift (/s)"},
  "stats.help.drift": {"pt": "Inclinação de uma reta ajustada ao trecho, na unidade da figura por segundo. Mostra se o sinal ainda está subindo ou caindo.", "en": "Slope of a line fitted to the stretch, in the figure unit per second. Shows whether the signal is still rising or falling."},
  "stats.col.noise": {"pt": "ruído", "en": "noise"},
  "stats.help.noise": {"pt": "Dispersão que sobra depois de remover essa reta. É a flutuação do sinal sem a tendência.", "en": "Spread left after removing that line. It is the fluctuation of the signal without the trend."},
  "stats.col.settle": {"pt": "regime", "en": "steady state"},
  "stats.help.settleMean": {"pt": "Média da janela de regime, no fim do intervalo. É o valor que se costuma reportar como patamar.", "en": "Mean of the steady-state window, at the end of the interval. It is the value usually reported as the level."},
  "stats.col.delta": {"pt": "Δ vs ref.", "en": "Δ vs ref."},
  "stats.help.delta": {"pt": "Diferença de amplitude para o intervalo de referência. Usa a média de regime quando há janela definida; senão, a média do intervalo.", "en": "Difference in amplitude to the reference interval. Uses the steady-state mean when a window is set; otherwise, the mean of the interval."},
  "stats.col.reference": {"pt": "referência", "en": "reference"},
  "stats.help.reference": {"pt": "Qual intervalo entrou nessa conta.", "en": "Which interval went into that calculation."},
  "stats.help.stepTable": {"pt": "Tabela de degraus", "en": "Step table"},
  "stats.help.beforeAfter": {"pt": "antes, depois", "en": "before, after"},
  "stats.help.beforeAfterText": {"pt": "Médias das janelas imediatamente antes e depois da marcação.", "en": "Means of the windows right before and right after the marker."},
  "stats.col.step": {"pt": "degrau", "en": "step"},
  "stats.col.spread": {"pt": "dispersão", "en": "spread"},
  "stats.help.spread": {"pt": "Desvios dos dois lados combinados (√(σ₁² + σ₂²)). Indica se o degrau se destaca da flutuação — não é a incerteza da média.", "en": "Deviations of both sides combined (√(σ₁² + σ₂²)). Shows whether the step stands out from the fluctuation — it is not the uncertainty of the mean."},
  "stats.help.uncertainty": {"pt": "Com dados filtrados as amostras vizinhas são parecidas entre si, então σ/√n subestima a incerteza. Para incerteza de verdade, compare ciclos repetidos do mesmo patamar.", "en": "With filtered data, neighbouring samples resemble each other, so σ/√n underestimates the uncertainty. For a real uncertainty, compare repeated cycles of the same level."},
  "stats.intro": {"pt": "As marcações delimitam os intervalos; o cálculo usa as curvas marcadas e a mesma unidade da figura.", "en": "The markers delimit the intervals; the calculation uses the checked curves and the same unit as the figure."},
