  "peaks.title": {"pt": "Picos e vales", "en": "Peaks and valleys"},
  "peaks.help.choose": {"pt": "O que você escolhe (barra lateral)", "en": "What you choose (sidebar)"},
  "peaks.help.maxMin": {"pt": "Máximos / Mínimos", "en": "Maxima / Minima"},
  "peaks.help.maxMinText": {"pt": "Quais extremos procurar: picos (reflexão de uma FBG, ressonâncias) e vales (transmissão, bandas de atenuação de TFBG/LPG, franjas de interferômetro).", "en": "Which extrema to look for: peaks (reflection of an FBG, resonances) and valleys (transmission, attenuation bands of TFBG/LPG, interferometer fringes)."},
  "peaks.help.prominence": {"pt": "Quanto o extremo precisa se destacar da vizinhança, na unidade da intensidade. Vazio = 5% da faixa do espectro. Aumente para ignorar ondulações de ruído.", "en": "How much the extremum must stand out from its surroundings, in the intensity unit. Empty = 5% of the spectrum's range. Raise it to ignore noise ripples."},
  "peaks.help.minDistance": {"pt": "Extremos mais próximos que isso viram um só; fica o mais proeminente.", "en": "Extrema closer than this become one; the most prominent stays."},
  "peaks.help.maxPerType": {"pt": "Mantém só os N extremos mais proeminentes de cada tipo.", "en": "Keeps only the N most prominent extrema of each type."},
  "peaks.help.table": {"pt": "Tabela", "en": "Table"},
  "peaks.help.lambda": {"pt": "Posição do extremo refinada por uma parábola nos 3 pontos em torno dele: resolução abaixo do passo da grade do espectro.", "en": "Position of the extremum refined by a parabola through the 3 points around it: resolution below the grid step of the spectrum."},
  "peaks.col.fit": {"pt": "λ ajuste (nm)", "en": "λ fit (nm)"},
  "peaks.help.fit": {"pt": "Vértice da parábola de mínimos quadrados pelos pontos do fundo do vale (ou do topo do pico), a até ⅓ da largura de cada lado. Usa dezenas de pontos, então o ruído pesa bem menos; é a posição padrão da evolução entre arquivos.", "en": "Vertex of the least-squares parabola through the points at the bottom of the valley (or the top of the peak), up to ⅓ of the width on each side. It uses dozens of points, so noise weighs much less; it is the default position of the evolution between files."},
  "peaks.col.intensity": {"pt": "Intensidade", "en": "Intensity"},
  "peaks.help.intensity": {"pt": "Valor no extremo (no pico ou no fundo do vale).", "en": "Value at the extremum (at the peak or at the bottom of the valley)."},
  "peaks.col.prominence": {"pt": "Proeminência", "en": "Prominence"},
  "peaks.help.prominenceCol": {"pt": "Altura do pico, ou profundidade do vale, em relação à base mais alta entre os dois lados. Em dB, num vale, é o contraste (extinção) da banda.", "en": "Height of the peak, or depth of the valley, relative to the higher base of the two sides. In dB, for a valley, it is the contrast (extinction) of the band."},
  "peaks.help.width": {"pt": "FWHM / Banda 3 dB", "en": "FWHM / 3 dB band"},
  "peaks.help.widthText": {"pt": "Largura no nível descrito acima, com interpolação entre amostras. Aparece como linha tracejada no gráfico.", "en": "Width at the level described above, interpolated between samples. It shows as a dashed line on the plot."},
  "peaks.help.q": {"pt": "λ dividido pela largura: seletividade da ressonância (quanto maior, mais estreita).", "en": "λ divided by the width: the selectivity of the resonance (the higher, the narrower)."},
  "peaks.col.centroid": {"pt": "Centroide (nm)", "en": "Centroid (nm)"},
  "peaks.help.centroid": {"pt": "Centro de massa da região acima do nível da largura. Menos sensível a ruído e a assimetrias que o ponto de máximo; é como muitos interrogadores demodulam FBGs.", "en": "Center of mass of the region above the width level. Less sensitive to noise and asymmetry than the maximum point; it is how many interrogators demodulate FBGs."},
  "peaks.col.spacing": {"pt": "Δλ anterior (nm)", "en": "Δλ to previous (nm)"},
  "peaks.help.spacing": {"pt": "Distância ao extremo anterior do mesmo tipo: FSR local de interferômetros e espaçamento entre modos de casca em TFBG/LPG.", "en": "Distance to the previous extremum of the same type: local FSR of interferometers and spacing between cladding modes in TFBG/LPG."},
  "peaks.help.summary": {"pt": "Resumo de cada traço", "en": "Summary of each trace"},
  "peaks.help.global": {"pt": "Máximo / mínimo global", "en": "Global maximum / minimum"},
  "peaks.help.globalText": {"pt": "Maior e menor valor do espectro (podem estar nas bordas, onde a busca de extremos não procura).", "en": "Highest and lowest value of the spectrum (they may be at the edges, where the extrema search does not look)."},
  "peaks.help.sideLobe": {"pt": "Supressão de lóbulo lateral", "en": "Side lobe suppression"},
  "peaks.help.sideLobeText": {"pt": "Diferença entre os dois maiores picos encontrados (SLSR de uma FBG; em dB se a escala for dB).", "en": "Difference between the two largest peaks found (SLSR of an FBG; in dB if the scale is dB)."},
  "peaks.help.fsr": {"pt": "FSR médio", "en": "Mean FSR"},
  "peaks.help.fsrText": {"pt": "Média dos Δλ entre extremos vizinhos de cada tipo.", "en": "Mean of the Δλ between neighbouring extrema of each type."},
  "peaks.help.resolution": {"pt": "Resolução", "en": "Resolution"},
  "peaks.help.resolutionText": {"pt": "Passo típico da grade em λ; a proeminência usada também é informada.", "en": "Typical grid step in λ; the prominence used is reported too."},
  "peaks.help.measured": {"pt": "Tudo é medido no espectro inteiro já preparado (recorte, suavização, normalização), não na versão decimada do gráfico.", "en": "Everything is measured on the whole prepared spectrum (cropping, smoothing, normalization), not on the thinned version of the plot."},
  "spectraEmpty.title": {"pt": "Adicione os espectros ópticos", "en": "Add the optical spectra"},
  "spectraEmpty.formats": {"pt": "intensidade × comprimento de onda; vários traços por arquivo são aceitos", "en": "intensity × wavelength; several traces per file are accepted"},
  "spectraEmpty.drop": {"pt": "Solte aqui os arquivos de espectro", "en": "Drop the spectrum files here"},
