  "viz.copyFigure": {"pt": "Copiar figura", "en": "Copy figure"},
  "viz.downloadFigure": {"pt": "Baixar figura", "en": "Download figure"},
  "viz.placeholder": {"pt": "A figura de publicação aparecerá aqui.", "en": "The publication figure will show up here."},
  "gate.hint": {"pt": "Um projeto guarda os arquivos escolhidos, o processamento de cada um, as marcações e o estilo da figura. Excluir um projeto apaga só o projeto: os arquivos de dados e os CSVs processados ficam. Atalhos: <kbd>Ctrl</kbd>+<kbd>Enter</kbd> processa (ou atualiza a figura) · <kbd>Ctrl</kbd>+<kbd>S</kbd> salva o projeto.", "en": "A project keeps the chosen files, the processing of each one, the markers and the figure style. Deleting a project deletes only the project: the data files and the processed CSVs stay. Shortcuts: <kbd>Ctrl</kbd>+<kbd>Enter</kbd> processes (or updates the figure) · <kbd>Ctrl</kbd>+<kbd>S</kbd> saves the project."},
  "sensors.howToText": {"pt": "Nome, banda permitida (nm) e sensibilidade térmica K<sub>T</sub> (pm/°C) de cada grade. O K<sub>T</sub> vem da calibração em temperatura e é usado pela compensação de temperatura. O setup salvo fica em data/setups e serve para outras aquisições da mesma montagem.", "en": "Name, allowed band (nm) and thermal sensitivity K<sub>T</sub> (pm/°C) of each grating. K<sub>T</sub> comes from the temperature calibration and is used by the temperature compensation. The saved setup goes in data/setups and serves other acquisitions with the same assembly."},
  "tempcomp.note": {"pt": "Δλ<sub>comp</sub> = Δλ<sub>s</sub> − (K<sub>T,s</sub>/K<sub>T,r</sub>)·Δλ<sub>r</sub>: tira de cada sensor a parte térmica medida pela rede de referência. O K<sub>T</sub> de cada rede fica no cartão Sensores; o sensor sem K<sub>T</sub> usa o k ao lado. Precisa do Δλ (ligado junto).", "en": "Δλ<sub>comp</sub> = Δλ<sub>s</sub> − (K<sub>T,s</sub>/K<sub>T,r</sub>)·Δλ<sub>r</sub>: removes from each sensor the thermal part measured by the reference grating. The K<sub>T</sub> of each grating is in the Sensors card; a sensor without K<sub>T</sub> uses the k beside it. Needs Δλ (turned on with it)."},
  "spectra.uploadHint": {"pt": "Uma pasta enviada fica em data/uploads/&lt;pasta&gt;. Arquivos em subpastas de data/raw também aparecem agrupados por pasta, com “adicionar todos”.", "en": "An uploaded folder goes in data/uploads/&lt;folder&gt;. Files in subfolders of data/raw also show up grouped by folder, with “add all”."},
  "stats.help.settle": {"pt": "Quantos segundos do <em>fim</em> de cada intervalo entram na média de regime. Serve para ignorar o transitório logo depois da marcação. Vazio = o intervalo inteiro.", "en": "How many seconds from the <em>end</em> of each interval go into the steady-state mean. It ignores the transient right after the marker. Empty = the whole interval."},
  "stats.help.compare": {"pt": "<em>Intervalo anterior</em>: o degrau de um patamar para o seguinte. <em>Primeiro intervalo</em>: a variação acumulada desde a linha de base. <em>Não comparar</em>: só as estatísticas de cada intervalo.", "en": "<em>Previous interval</em>: the step from one level to the next. <em>First interval</em>: the accumulated change since the baseline. <em>Do not compare</em>: only the statistics of each interval."},
  "stats.help.stepText": {"pt": "<em>depois − antes</em>: o quanto o sinal mudou naquela marcação.", "en": "<em>after − before</em>: how much the signal changed at that marker."},
  "evo.intro": {"pt": "Usa os espectros do projeto em ordem de aquisição (cabeçalho <code>Date:</code> ou hora no nome do arquivo, <code>..._09-30-15-250</code>). Marque o λ de referência e clique no vale, no gráfico do espectro acima.", "en": "Uses the project's spectra in acquisition order (<code>Date:</code> header or time in the file name, <code>..._09-30-15-250</code>). Mark λ ref and click the valley, on the spectrum plot above."},
  "peaks.help.scale": {"pt": "<em>Linear</em>: a largura é medida a meia proeminência (FWHM). <em>dB/dBm</em>: banda de 3 dB — 3 dB abaixo do pico ou acima do fundo do vale. Use dB quando o arquivo vem do OSA em dBm; vale com menos de 3 dB de profundidade fica sem largura.", "en": "<em>Linear</em>: the width is measured at half prominence (FWHM). <em>dB/dBm</em>: 3 dB band — 3 dB below the peak or above the bottom of the valley. Use dB when the file comes from the OSA in dBm; a valley less than 3 dB deep has no width."},
  "header.projectNameTitle": {"pt": "Nome do projeto. Salvar com outro nome cria uma cópia.", "en": "Project name. Saving under another name makes a copy."},
  "header.projectsTitle": {"pt": "Abrir, criar ou excluir projetos", "en": "Open, create or delete projects"},
  "header.dirtyTitle": {"pt": "Há alterações que ainda não foram salvas", "en": "There are changes that are not saved yet"},
  "header.autosaveTitle": {"pt": "Salva o projeto sozinho, alguns segundos depois de cada mudança", "en": "Saves the project by itself, a few seconds after each change"},
  "header.undoTitle": {"pt": "Desfazer (Ctrl+Z)", "en": "Undo (Ctrl+Z)"},
